    [Fact]
    public void NativeJsonAdapter_RoundTrip_WorkbookTheme()
    {
        var workbook = new Workbook("ThemeTest");
        workbook.AddSheet("Sheet1");
        workbook.Theme = WorkbookTheme.Office
            .WithName("FreeX Test Theme")
            .WithFonts("Aptos Display", "Aptos")
            .WithEffects("FreeXEffects")
            .WithColor(WorkbookThemeColorSlot.Accent1, new CellColor(12, 34, 56))
            .WithColor(WorkbookThemeColorSlot.Hyperlink, new CellColor(1, 99, 193))
            .WithNativeThemeSupplementXml("""
                <a:objectDefaults xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">
                    <a:spDef/>
                </a:objectDefaults>
                """)
            .WithSupplementalMetadata(
                [
                    new WorkbookThemeAlternateColorScheme(
                        "Json Alternate",
                        new Dictionary<WorkbookThemeColorSlot, CellColor>
                        {
                            [WorkbookThemeColorSlot.Accent1] = new(17, 34, 51)
                        },
                        """
                        <a:clrScheme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="Json Alternate">
                            <a:accent1><a:srgbClr val="112233"/></a:accent1>
                        </a:clrScheme>
                        """)
                ],
                hasObjectDefaults: true,
                new WorkbookThemeObjectDefaults(
                    Shape: new WorkbookThemeShapeObjectDefault(
                        FillThemeColor: new WorkbookThemeColorReference(WorkbookThemeColorSlot.Accent2, 0.4),
                        OutlineColor: new CellColor(44, 55, 66),
                        OutlineWidthPoints: 1.75),
                    Text: new WorkbookThemeTextObjectDefault(
                        TextThemeColor: new WorkbookThemeColorReference(WorkbookThemeColorSlot.Dark1),
                        Typeface: "Aptos")));

        var adapter = new NativeJsonAdapter();
        using var ms = new MemoryStream();
        adapter.Save(workbook, ms);
        ms.Position = 0;

        var loaded = adapter.Load(ms);

        loaded.Theme.Name.Should().Be("FreeX Test Theme");
        loaded.Theme.MajorFontName.Should().Be("Aptos Display");
        loaded.Theme.MinorFontName.Should().Be("Aptos");
        loaded.Theme.EffectsName.Should().Be("FreeXEffects");
        loaded.Theme.GetColor(WorkbookThemeColorSlot.Accent1).Should().Be(new CellColor(12, 34, 56));
        loaded.Theme.GetColor(WorkbookThemeColorSlot.Hyperlink).Should().Be(new CellColor(1, 99, 193));
        loaded.Theme.NativeThemeSupplementXml.Should().Contain("objectDefaults");
        loaded.Theme.HasObjectDefaults.Should().BeTrue();
        loaded.Theme.ObjectDefaults.Should().NotBeNull();
        loaded.Theme.ObjectDefaults!.Shape.Should().Be(new WorkbookThemeShapeObjectDefault(
            new WorkbookThemeColorReference(WorkbookThemeColorSlot.Accent2, 0.4),
            null,
            null,
            new CellColor(44, 55, 66),
            1.75));
        loaded.Theme.ObjectDefaults.Text.Should().Be(new WorkbookThemeTextObjectDefault(
            new WorkbookThemeColorReference(WorkbookThemeColorSlot.Dark1),
            null,
            "Aptos"));
        loaded.Theme.AlternateColorSchemes.Should().ContainSingle()
            .Which.GetColor(WorkbookThemeColorSlot.Accent1)
            .Should().Be(new CellColor(17, 34, 51));
    }

