    [Fact]
    public void NativeJsonAdapter_Save_SkipsCrossSheetVisualObjects()
    {
        // A visual object is owned by (and saved under) the sheet it is ANCHORED on - never by
        // whatever sheet an optional cross-sheet reference (a linked picture's LinkedSourceRange)
        // happens to point at. A picture anchored on Sheet1 with a LinkedSourceRange on "Other" is
        // therefore still Sheet1's picture and must be saved there (P24 - previously this
        // configuration satisfied neither sheet's save filter and the picture was silently dropped
        // from the file entirely); only an object truly ANCHORED on a different sheet is excluded here.
        var workbook = new Workbook("ObjectCrossSheetSaveTest");
        var sheet = workbook.AddSheet("Sheet1");
        var otherSheet = workbook.AddSheet("Other");
        sheet.Pictures.Add(new PictureModel
        {
            Anchor = new CellAddress(sheet.Id, 2, 2),
            LinkedSourceRange = new GridRange(
                new CellAddress(sheet.Id, 1, 1),
                new CellAddress(sheet.Id, 2, 2)),
            Width = 90,
            Height = 60
        });
        sheet.Pictures.Add(new PictureModel
        {
            Anchor = new CellAddress(otherSheet.Id, 2, 2),
            Width = 90,
            Height = 60
        });
        sheet.Pictures.Add(new PictureModel
        {
            Anchor = new CellAddress(sheet.Id, 3, 2),
            LinkedSourceRange = new GridRange(
                new CellAddress(otherSheet.Id, 1, 1),
                new CellAddress(otherSheet.Id, 2, 2)),
            Width = 90,
            Height = 60
        });
        sheet.TextBoxes.Add(new TextBoxModel
        {
            Anchor = new CellAddress(sheet.Id, 4, 2),
            Text = "Note"
        });
        sheet.TextBoxes.Add(new TextBoxModel
        {
            Anchor = new CellAddress(otherSheet.Id, 4, 2),
            Text = "Other"
        });
        sheet.DrawingShapes.Add(new DrawingShapeModel
        {
            Anchor = new CellAddress(sheet.Id, 5, 2)
        });
        sheet.DrawingShapes.Add(new DrawingShapeModel
        {
            Anchor = new CellAddress(otherSheet.Id, 5, 2)
        });

        var ms = new MemoryStream();
        new NativeJsonAdapter().Save(workbook, ms);
        ms.Position = 0;

        using var document = JsonDocument.Parse(ms);
        var sheetJson = document.RootElement.GetProperty("Sheets")[0];
        sheetJson.GetProperty("Pictures").EnumerateArray()
            .Select(picture => picture.GetProperty("Anchor").GetString())
            .Should().BeEquivalentTo(["B2", "B3"],
                "both pictures anchored on Sheet1 must be saved there, regardless of where either " +
                "picture's own LinkedSourceRange points - only the picture anchored on \"Other\" is excluded");
        sheetJson.GetProperty("TextBoxes").EnumerateArray()
            .Should().ContainSingle()
            .Which.GetProperty("Anchor").GetString().Should().Be("B4");
        sheetJson.GetProperty("DrawingShapes").EnumerateArray()
            .Should().ContainSingle()
            .Which.GetProperty("Anchor").GetString().Should().Be("B5");
    }

    [Fact]
    public void NativeJsonAdapter_Save_PersistsCrossSheetCharts()
    {
        // A chart is hosted by Sheet.Charts membership, independent of where its data range lives.
        // Cross-sheet charts (data range on another sheet) must be persisted, tagged with the
        // data-source sheet name so the range rebinds correctly on load instead of being dropped.
        var workbook = new Workbook("ChartCrossSheetSaveTest");
        var sheet = workbook.AddSheet("Sheet1");
        var otherSheet = workbook.AddSheet("Other");
        sheet.Charts.Add(new ChartModel
        {
            Type = ChartType.Column,
            DataRange = new GridRange(
                new CellAddress(sheet.Id, 1, 1),
                new CellAddress(sheet.Id, 3, 2)),
            Title = "On Sheet"
        });
        sheet.Charts.Add(new ChartModel
        {
            Type = ChartType.Line,
            DataRange = new GridRange(
                new CellAddress(otherSheet.Id, 1, 1),
                new CellAddress(otherSheet.Id, 3, 2)),
            Title = "Other Sheet"
        });

        var ms = new MemoryStream();
        new NativeJsonAdapter().Save(workbook, ms);
        ms.Position = 0;

        using var document = JsonDocument.Parse(ms);
        var sheetJson = document.RootElement.GetProperty("Sheets")[0];
        var charts = sheetJson.GetProperty("Charts").EnumerateArray().ToList();
        charts.Should().HaveCount(2, "both the same-sheet and cross-sheet charts must be persisted");

        var sameSheet = charts.Single(c => c.GetProperty("Title").GetString() == "On Sheet");
        sameSheet.GetProperty("DataRange").GetString().Should().Be("A1:B3");
        sameSheet.TryGetProperty("DataRangeSheetName", out var sameSheetName).Should().BeTrue();
        sameSheetName.ValueKind.Should().Be(JsonValueKind.Null,
            "a same-sheet chart needs no data-range sheet name");

        var crossSheet = charts.Single(c => c.GetProperty("Title").GetString() == "Other Sheet");
        crossSheet.GetProperty("DataRange").GetString().Should().Be("A1:B3");
        crossSheet.GetProperty("DataRangeSheetName").GetString().Should().Be("Other");
    }

