    [Fact]
    public void NativeJsonAdapter_RoundTrip_ProtectionState()
    {
        var workbook = new Workbook("ProtectionNativeTest");
        workbook.IsStructureProtected = true;
        workbook.StructureProtectionPassword = "workbook-secret";
        workbook.ProtectionMetadata = MakeBag("workbookProtection",
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["algorithmName"] = "SHA-512",
                ["hashValue"] = "def456",
                ["saltValue"] = "salt456",
                ["spinCount"] = "100000",
                ["lockWindows"] = "1"
            },
            ["<fx:workbookProtectionNativeChild xmlns:fx=\"urn:freex:test\" id=\"first\" />"]);
        var sheet = workbook.AddSheet("S1");
        sheet.IsProtected = true;
        sheet.ProtectionPassword = "sheet-secret";
        sheet.ProtectionPermissions.Clear();
        sheet.ProtectionPermissions.Add(SheetProtectionPermission.SelectUnlockedCells);
        sheet.ProtectionPermissions.Add(SheetProtectionPermission.FormatCells);
        sheet.ProtectionMetadata = MakeBag("sheetProtection",
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["algorithmName"] = "SHA-512",
                ["hashValue"] = "AQIDBA==",
                ["saltValue"] = "BQYHCA==",
                ["spinCount"] = "100000",
                ["objects"] = "1"
            },
            ["<fx:sheetProtectionNativeChild xmlns:fx=\"urn:freex:test\" id=\"first\" />"]);
        sheet.AllowEditRanges.Add(new GridRange(
            new CellAddress(sheet.Id, 2, 2),
            new CellAddress(sheet.Id, 3, 3)));

        var ms = new MemoryStream();
        var adapter = new NativeJsonAdapter();
        adapter.Save(workbook, ms);
        ms.Position = 0;

        var loaded = adapter.Load(ms);

        loaded.IsStructureProtected.Should().BeTrue();
        // After a save+load round-trip the password is stored as a sha256 hash, not plaintext.
        ProtectionPasswordHelper.VerifyStoredPassword(loaded.StructureProtectionPassword, "workbook-secret")
            .Should().BeTrue("the stored hash must verify against the original password");
        loaded.ProtectionMetadata.Should().BeEquivalentTo(workbook.ProtectionMetadata);
        var loadedSheet = loaded.GetSheetAt(0);
        loadedSheet.IsProtected.Should().BeTrue();
        ProtectionPasswordHelper.VerifyStoredPassword(loadedSheet.ProtectionPassword, "sheet-secret")
            .Should().BeTrue("the stored hash must verify against the original password");
        loadedSheet.ProtectionPermissions.Should().Equal(
            SheetProtectionPermission.SelectUnlockedCells,
            SheetProtectionPermission.FormatCells);
        loadedSheet.ProtectionMetadata.Should().BeEquivalentTo(sheet.ProtectionMetadata);
        var allowEditRange = loadedSheet.AllowEditRanges.Should().ContainSingle().Subject;
        allowEditRange.Start.ToA1().Should().Be("B2");
        allowEditRange.End.ToA1().Should().Be("C3");
    }

    [Fact]
    public void NativeJsonAdapter_SaveLoadSave_KeepsProtectionPasswordHashesStable()
    {
        var workbook = new Workbook("ProtectionNativeHashStabilityTest");
        workbook.IsStructureProtected = true;
        workbook.StructureProtectionPassword = "workbook-secret";
        var sheet = workbook.AddSheet("S1");
        sheet.IsProtected = true;
        sheet.ProtectionPassword = "sheet-secret";

        var adapter = new NativeJsonAdapter();
        using var first = new MemoryStream();
        adapter.Save(workbook, first);
        var firstBytes = first.ToArray();
        first.Position = 0;

        var loaded = adapter.Load(first);
        using var second = new MemoryStream();
        adapter.Save(loaded, second);
        var secondBytes = second.ToArray();

        using var firstJson = JsonDocument.Parse(firstBytes);
        using var secondJson = JsonDocument.Parse(secondBytes);
        var firstWorkbookHash = firstJson.RootElement.GetProperty("StructureProtectionPassword").GetString();
        var secondWorkbookHash = secondJson.RootElement.GetProperty("StructureProtectionPassword").GetString();
        var firstSheetHash = firstJson.RootElement.GetProperty("Sheets")[0].GetProperty("ProtectionPassword").GetString();
        var secondSheetHash = secondJson.RootElement.GetProperty("Sheets")[0].GetProperty("ProtectionPassword").GetString();

        secondWorkbookHash.Should().Be(firstWorkbookHash);
        secondSheetHash.Should().Be(firstSheetHash);
        ProtectionPasswordHelper.VerifyStoredPassword(secondWorkbookHash, "workbook-secret").Should().BeTrue();
        ProtectionPasswordHelper.VerifyStoredPassword(secondSheetHash, "sheet-secret").Should().BeTrue();
    }

