        var loaded = new XlsxFileAdapter().Load(saved);
        var loadedChart = loaded.GetSheetAt(0).Charts.Should().ContainSingle().Subject;
        loadedChart.YAxisCrosses.Should().Be(ChartAxisCrosses.Custom);
        loadedChart.YAxisCrossesAt.Should().Be(5);
        loadedChart.YAxisCrossBetween.Should().Be(ChartAxisCrossBetween.MidCategory);
    }

