    [Fact]
    public void XlsxAdapter_SaveLoadedWorkbook_PreservesChartCustomErrorBarReferences()
    {
        var workbook = new Workbook("ChartCustomErrorBarsPackagePreserve");
        var sheet = workbook.AddSheet("Sheet1");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("Month"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 2), new TextValue("Sales"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 3), new TextValue("Plus"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 4), new TextValue("Minus"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 1), new TextValue("Jan"));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 1), new TextValue("Feb"));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 1), new TextValue("Mar"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 2), new NumberValue(10));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 2), new NumberValue(20));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 2), new NumberValue(30));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 3), new NumberValue(1));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 3), new NumberValue(2));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 3), new NumberValue(3));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 4), new NumberValue(0.5));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 4), new NumberValue(1.5));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 4), new NumberValue(2.5));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddMinimalColumnChartPackage(source, chartXml: """
            <c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart"
                          xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">
              <c:chart>
                <c:plotArea>
                  <c:barChart>
                    <c:barDir val="col"/>
                    <c:ser>
                      <c:tx><c:strRef><c:f>Sheet1!$B$1</c:f></c:strRef></c:tx>
                      <c:cat><c:strRef><c:f>Sheet1!$A$2:$A$4</c:f></c:strRef></c:cat>
                      <c:val><c:numRef><c:f>Sheet1!$B$2:$B$4</c:f></c:numRef></c:val>
                      <c:errBars>
                        <c:errDir val="y"/>
                        <c:errBarType val="both"/>
                        <c:errValType val="cust"/>
                        <c:plus><c:numRef><c:f>Sheet1!$C$2:$C$4</c:f></c:numRef></c:plus>
                        <c:minus><c:numRef><c:f>Sheet1!$D$2:$D$4</c:f></c:numRef></c:minus>
                      </c:errBars>
                    </c:ser>
                  </c:barChart>
                </c:plotArea>
              </c:chart>
            </c:chartSpace>
            """);

        source.Position = 0;
        var loaded = adapter.Load(source);
        var loadedChart = loaded.GetSheetAt(0).Charts.Should().ContainSingle().Subject;
        loadedChart.ErrorBarKind.Should().Be(ChartErrorBarKind.Custom);
        loadedChart.ErrorBarPlusRangeFormula.Should().Be("Sheet1!$C$2:$C$4");
        loadedChart.ErrorBarMinusRangeFormula.Should().Be("Sheet1!$D$2:$D$4");

        var saved = new MemoryStream();
        adapter.Save(loaded, saved);
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: true);
        XNamespace chartNs = "http://schemas.openxmlformats.org/drawingml/2006/chart";
        var chartXml = LoadPackageXml(archive.GetEntry("xl/charts/chart1.xml")!);
        var errorBars = chartXml.Descendants(chartNs + "errBars").Should().ContainSingle().Subject;
        errorBars.Element(chartNs + "errValType")!.Attribute("val")!.Value.Should().Be("cust");
        errorBars.Element(chartNs + "plus")!.Descendants(chartNs + "f").Single().Value.Should().Be("Sheet1!$C$2:$C$4");
        errorBars.Element(chartNs + "minus")!.Descendants(chartNs + "f").Single().Value.Should().Be("Sheet1!$D$2:$D$4");
    }

