    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_PreservesUnknownPackagePartsAlongsideModelEdits()
    {
        var workbook = new Workbook("UnknownPartTest");
        var sheet = workbook.AddSheet("S1");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("kept"));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddUnknownPackagePart(source, "customXml/item1.xml", "<freex-test />");

        source.Position = 0;
        var loaded = adapter.Load(source);
        var loadedSheet = loaded.GetSheetAt(0);
        loadedSheet.SetCell(new CellAddress(loadedSheet.Id, 1, 1), new TextValue("edited"));
        var saved = new MemoryStream();
        adapter.Save(loaded, saved);
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: false);
        archive.GetEntry("customXml/item1.xml").Should().NotBeNull(
            "XLSX files opened from Excel should retain unsupported package parts when FreeX saves modeled edits");

        saved.Position = 0;
        var roundTripped = adapter.Load(saved);
        roundTripped.GetSheetAt(0).GetValue(1, 1).Should().Be(new TextValue("edited"));
    }

    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_PreservesVbaProjectPackageGraphAlongsideModelEdits()
    {
        var workbook = new Workbook("MacroPackageGraphRetentionTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("kept"));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddMinimalVbaProjectPackage(source);

        source.Position = 0;
        var loaded = adapter.Load(source);
        var loadedSheet = loaded.GetSheetAt(0);
        loadedSheet.SetCell(new CellAddress(loadedSheet.Id, 1, 1), new TextValue("edited"));

        // R70-io-vba-6-1: the plain Save (used for a genuine .xlsx target) now intentionally DROPS
        // a source's VBA project -- matching Excel's own Save-As-plain-format behavior -- so this
        // "preserve the VBA package graph across a model edit" scenario is now exercised via the
        // VBA-preserving entry point (what XlsmFileAdapter/XltmFileAdapter delegate to) rather than
        // the plain Save. See XlsmFileAdapterTests' Xlsx_SaveAs_FromMacroEnabledSource_* tests for
        // the (new) plain-Save drop behavior.
        var saved = new MemoryStream();
        adapter.SavePreservingVbaProject(loaded, saved);
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: false);
        archive.GetEntry("xl/vbaProject.bin").Should().NotBeNull();

        XNamespace packageRelNs = "http://schemas.openxmlformats.org/package/2006/relationships";
        XNamespace contentTypeNs = "http://schemas.openxmlformats.org/package/2006/content-types";
        var workbookRelsXml = LoadPackageXml(archive.GetEntry("xl/_rels/workbook.xml.rels")!);
        workbookRelsXml.Root!
            .Elements(packageRelNs + "Relationship")
            .Should()
            .ContainSingle(element =>
                (string?)element.Attribute("Type") == "http://schemas.microsoft.com/office/2006/relationships/vbaProject" &&
                (string?)element.Attribute("Target") == "vbaProject.bin");

        var contentTypesXml = LoadPackageXml(archive.GetEntry("[Content_Types].xml")!);
        contentTypesXml.Root!
            .Elements(contentTypeNs + "Override")
            .Should()
            .ContainSingle(element =>
                (string?)element.Attribute("PartName") == "/xl/workbook.xml" &&
                (string?)element.Attribute("ContentType") == "application/vnd.ms-excel.sheet.macroEnabled.main+xml");
        contentTypesXml.Root!
            .Elements(contentTypeNs + "Override")
            .Should()
            .ContainSingle(element =>
