    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_PreservesWorksheetSingleXmlCellsAlongsideModelEdits()
    {
        var workbook = new Workbook("SingleXmlCellsRetentionTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("kept"));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddWorksheetSingleXmlCells(source);

        source.Position = 0;
        var loaded = adapter.Load(source);
        var loadedSheet = loaded.GetSheetAt(0);
        loadedSheet.SingleXmlCells.Should().NotBeNull();
        loadedSheet.SingleXmlCells!.Cells.Should().ContainSingle(cell =>
            cell.Id == 1 &&
            cell.Reference == "A1" &&
            cell.XmlCellPropertyId == 1);
        loadedSheet.SingleXmlCells.NativeAttributes["nativeSingleXmlCellsAttr"] = "kept";
        loadedSheet.SingleXmlCells.NativeAttributes["invalid singleXmlCells attr"] = "skip";
        loadedSheet.SingleXmlCells.Cells[0].NativeAttributes["nativeSingleXmlCellAttr"] = "cell-kept";
        loadedSheet.SingleXmlCells.Cells[0].NativeAttributes["invalid singleXmlCell attr"] = "skip";
        loadedSheet.SetCell(new CellAddress(loadedSheet.Id, 1, 1), new TextValue("edited"));

        var saved = new MemoryStream();
        var save = () => adapter.Save(loaded, saved);

        save.Should().NotThrow();
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: false);
        var worksheetXml = LoadPackageXml(archive.GetEntry("xl/worksheets/sheet1.xml")!);
        XNamespace worksheetNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
        worksheetXml.Root!.Element(worksheetNs + "singleXmlCells").Should().BeNull();
        var singleXmlCells = ReadWorksheetSingleCellTableRootElement(archive);
        singleXmlCells.Should().NotBeNull();
        var singleXmlCell = singleXmlCells!.Elements(worksheetNs + "singleXmlCell").Should().ContainSingle().Which;
        singleXmlCell.Attribute("id")!.Value.Should().Be("1");
        singleXmlCell.Attribute("r")!.Value.Should().Be("A1");
        singleXmlCell.Attribute("connectionId")!.Value.Should().Be("1");
        singleXmlCell.Attribute("nativeSingleXmlCellAttr").Should().BeNull();
        singleXmlCells.Attribute("nativeSingleXmlCellsAttr").Should().BeNull();
        singleXmlCell.Element(worksheetNs + "xmlCellPr")!
            .Element(worksheetNs + "xmlPr")!
            .Attribute("xmlDataType")!
            .Value
            .Should()
            .Be("string");
    }

