    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_MergesPrimaryWorkbookViewMetadataAlongsideAdditionalViews()
    {
        var workbook = new Workbook("PrimaryWorkbookViewWithAdditionalViewsTest");
