    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_PreservesStylesheetNativeMetadata()
    {
        var workbook = new Workbook("StylesheetNativeMetadataRetentionTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("style metadata"));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddStylesheetNativeMetadata(source);

        source.Position = 0;
        var loaded = adapter.Load(source);
        loaded.GetSheetAt(0).SetCell(new CellAddress(loaded.GetSheetAt(0).Id, 2, 1), new TextValue("edited"));

        var saved = new MemoryStream();
        adapter.Save(loaded, saved);
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: false);
        var stylesXml = LoadPackageXml(archive.GetEntry("xl/styles.xml")!);
        XNamespace workbookNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
        XNamespace freexNs = "urn:freex:test";
        var colors = stylesXml.Root!.Element(workbookNs + "colors");
        colors.Should().NotBeNull();
        colors!.ToString().Should().Contain("rgb=\"FF010203\"");

        var tableStyles = stylesXml.Root!.Element(workbookNs + "tableStyles");
        tableStyles.Should().NotBeNull();
        tableStyles!.Attribute("defaultPivotStyle").Should().NotBeNull();
        tableStyles.Attribute("defaultPivotStyle")!.Value.Should().Be("PivotStyleMedium9");
        tableStyles.Elements(workbookNs + "tableStyle")
            .Any(element => element.Attribute("name")?.Value == "FreeXNativeTableStyle")
            .Should().BeTrue();
        tableStyles.Attribute("nativeTableStylesAttr").Should().BeNull();
        tableStyles.Element(XName.Get("tableStylesNativeChild", "urn:freex:test")).Should().BeNull();
        loaded.PivotTableStyles.Should().ContainSingle(style =>
            style.Name == "FreeXNativePivotStyle" &&
            style.AppliesToPivotTables &&
            !style.AppliesToTables &&
            style.Elements.Any(element =>
                element.Type == "wholeTable" &&
                element.DifferentialFormatId == 0));
        loaded.StructuredTableStyles.Should().ContainSingle(style =>
            style.Name == "FreeXNativeTableStyle" &&
            style.AppliesToTables &&
            !style.AppliesToPivotTables &&
            style.NativeXml != null &&
            style.NativeXml.Contains("tableStyleElement", StringComparison.Ordinal));
        tableStyles.Elements(workbookNs + "tableStyle")
            .Any(element => element.Attribute("name")?.Value == "FreeXNativePivotStyle" &&
                            element.Attribute("pivot")?.Value == "1" &&
                            element.Element(workbookNs + "tableStyleElement")?.Attribute("dxfId")?.Value == "0")
            .Should().BeTrue();
        var differentialStyles = stylesXml.Root!.Element(workbookNs + "dxfs");
        differentialStyles.Should().NotBeNull();
        var differentialStyle = differentialStyles!.Elements(workbookNs + "dxf").Should().ContainSingle().Subject;
        differentialStyle.Attribute("nativePivotDxf").Should().BeNull();
        differentialStyle.Element(freexNs + "pivotStyleDxfNativeChild").Should().BeNull();
        differentialStyle.Element(workbookNs + "fill").Should().NotBeNull();

        var extensionList = stylesXml.Root!.Element(workbookNs + "extLst");
        extensionList.Should().NotBeNull();
        extensionList!.ToString().Should().Contain("{FFEEDDCC-7788-6655-4433-22110099AABB}");
        extensionList.ToString().Should().Contain("FreeXNativeStylesExtension");
    }

