    [Fact]
    public void XlsxAdapter_Save_SanitizesAuthoredStructuredTableStyleNativeXml()
    {
        var workbook = new Workbook("AuthoredStructuredTableStyleMetadataTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("table style"));
        workbook.StructuredTableStyles.Add(new StructuredTableStyleModel
        {
            Name = "FreeXAuthoredTableStyle",
            AppliesToTables = true,
            AppliesToPivotTables = false,
            NativeXml = """
                <tableStyle xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" name="FreeXAuthoredTableStyle" pivot="0" table="1" count="1" customTableStyleAttr="kept">
                  <tableStyleElement type="wholeTable" dxfId="0" customElementAttr="kept" />
                </tableStyle>
                """
        });

        var saved = new MemoryStream();
        new XlsxFileAdapter().Save(workbook, saved);
        saved.Position = 0;

        using (var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: true))
        {
            var stylesXml = LoadPackageXml(archive.GetEntry("xl/styles.xml")!);
            XNamespace workbookNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
            var tableStyle = stylesXml.Root!
                .Element(workbookNs + "tableStyles")!
                .Elements(workbookNs + "tableStyle")
                .Where(element => element.Attribute("name")?.Value == "FreeXAuthoredTableStyle")
                .Should().ContainSingle()
                .Subject;
            tableStyle.Attribute("pivot")!.Value.Should().Be("0");
            tableStyle.Attribute("table")!.Value.Should().Be("1");
            tableStyle.Attribute("count")!.Value.Should().Be("1");
            tableStyle.Attribute("customTableStyleAttr").Should().BeNull();
            tableStyle.Element(workbookNs + "tableStyleElement")!
                .Attribute("customElementAttr")
                .Should()
                .BeNull();
        }

        saved.Position = 0;
        var loaded = new XlsxFileAdapter().Load(saved);
        loaded.StructuredTableStyles.Should().ContainSingle(style =>
            style.Name == "FreeXAuthoredTableStyle" &&
            style.NativeXml != null &&
            style.NativeXml.Contains("tableStyleElement", StringComparison.Ordinal) &&
            !style.NativeXml.Contains("customElementAttr", StringComparison.Ordinal));
    }

    [Fact]
    public void XlsxAdapter_Load_CustomStructuredTableStyle_AppliesSupportedDxfSemantics()
    {
        var workbook = new Workbook("StructuredTableStyleSemanticTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("Region"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 2), new TextValue("Sales"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 3), new TextValue("Orders"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 4), new TextValue("Margin"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 1), new TextValue("North"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 2), new NumberValue(12));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 3), new NumberValue(2));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 4), new NumberValue(3));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 1), new TextValue("South"));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 2), new NumberValue(18));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 3), new NumberValue(4));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 4), new NumberValue(5));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 1), new TextValue("West"));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 2), new NumberValue(24));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 3), new NumberValue(6));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 4), new NumberValue(7));
        sheet.SetCell(new CellAddress(sheet.Id, 5, 1), new TextValue("Total"));
        sheet.SetCell(new CellAddress(sheet.Id, 5, 2), new NumberValue(54));
        sheet.SetCell(new CellAddress(sheet.Id, 5, 3), new NumberValue(12));
        sheet.SetCell(new CellAddress(sheet.Id, 5, 4), new NumberValue(15));
        sheet.StructuredTables.Add(new StructuredTableModel
        {
            Id = 1,
            Name = "SalesTable",
            DisplayName = "SalesTable",
            Range = new GridRange(new CellAddress(sheet.Id, 1, 1), new CellAddress(sheet.Id, 5, 4)),
            HasAutoFilter = true,
            TotalsRowShown = true,
            HeaderRowCount = 1,
            TotalsRowCount = 1,
            StyleName = "FreeXSemanticTableStyle",
            ShowFirstColumn = true,
            ShowLastColumn = true,
            ShowRowStripes = true,
            Columns =
            {
                new StructuredTableColumnModel(1, "Region"),
                new StructuredTableColumnModel(2, "Sales"),
                new StructuredTableColumnModel(3, "Orders"),
                new StructuredTableColumnModel(4, "Margin")
            }
        });

        var columnSheet = workbook.AddSheet("ColumnStripes");
        for (var row = 1u; row <= 5; row++)
        {
            for (var col = 1u; col <= 4; col++)
                columnSheet.SetCell(new CellAddress(columnSheet.Id, row, col), new TextValue($"R{row}C{col}"));
        }

        columnSheet.StructuredTables.Add(new StructuredTableModel
        {
            Id = 2,
            Name = "ColumnStripeTable",
            DisplayName = "ColumnStripeTable",
            Range = new GridRange(new CellAddress(columnSheet.Id, 1, 1), new CellAddress(columnSheet.Id, 5, 4)),
            HasAutoFilter = true,
            HeaderRowCount = 1,
            StyleName = "FreeXSemanticTableStyle",
            ShowColumnStripes = true,
            Columns =
            {
                new StructuredTableColumnModel(1, "A"),
                new StructuredTableColumnModel(2, "B"),
                new StructuredTableColumnModel(3, "C"),
                new StructuredTableColumnModel(4, "D")
            }
        });

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddStructuredTableStyleSemanticMetadata(source);

        source.Position = 0;
        var loaded = adapter.Load(source);

        var loadedSheet = loaded.GetSheetAt(0);
        var loadedStyle = loaded.StructuredTableStyles.Should()
            .ContainSingle(style => style.Name == "FreeXSemanticTableStyle")
            .Subject;
        loadedStyle.NativeXml.Should().Contain("unsupportedSemantics=\"kept\"");
        var wholeTableElement = loadedStyle.Elements.Single(element => element.Type == "wholeTable");
        wholeTableElement.DifferentialFormatId.Should().Be(0);
        wholeTableElement.Format.Should().NotBeNull();
        wholeTableElement.Format!.FillColor.Should().Be(new CellColor(226, 240, 217));
        wholeTableElement.Format.FontColor.Should().Be(new CellColor(16, 32, 48));
        var headerRowElement = loadedStyle.Elements.Single(element => element.Type == "headerRow");
        headerRowElement.DifferentialFormatId.Should().Be(1);
        headerRowElement.Format.Should().NotBeNull();
        headerRowElement.Format!.FillColor.Should().Be(new CellColor(31, 78, 121));
        headerRowElement.Format.FontColor.Should().Be(CellColor.White);
        var firstRowStripeElement = loadedStyle.Elements.Single(element => element.Type == "firstRowStripe");
        firstRowStripeElement.Size.Should().Be(2);
        firstRowStripeElement.Format.Should().NotBeNull();
        firstRowStripeElement.Format!.FillColor.Should().Be(new CellColor(255, 242, 204));
        loadedStyle.Elements.Single(element => element.Type == "blankRow").Format.Should().BeNull();

        var headerStyle = loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 1, 2))!.StyleId);
        headerStyle.FillColor.Should().Be(new CellColor(31, 78, 121));
        headerStyle.FontColor.Should().Be(CellColor.White);
        headerStyle.Bold.Should().BeTrue();

        var firstHeaderStyle = loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 1, 1))!.StyleId);
        firstHeaderStyle.FillColor.Should().Be(new CellColor(112, 48, 160));
        firstHeaderStyle.FontColor.Should().Be(CellColor.White);

        var rowStripeStyle = loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 2, 2))!.StyleId);
        rowStripeStyle.FillColor.Should().Be(new CellColor(255, 242, 204));
        rowStripeStyle.FontColor.Should().Be(new CellColor(16, 32, 48));
        rowStripeStyle.Bold.Should().BeFalse();

        loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 3, 2))!.StyleId)
            .FillColor.Should().Be(new CellColor(255, 242, 204));
        loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 4, 2))!.StyleId)
            .FillColor.Should().Be(new CellColor(252, 228, 214));

        var firstColumnStyle = loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 2, 1))!.StyleId);
        firstColumnStyle.FontColor.Should().Be(new CellColor(192, 0, 0));
        firstColumnStyle.Bold.Should().BeTrue();
        var lastColumnStyle = loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 2, 4))!.StyleId);
        lastColumnStyle.FontColor.Should().Be(new CellColor(0, 32, 96));
        lastColumnStyle.Bold.Should().BeTrue();

        var totalStyle = loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 5, 2))!.StyleId);
        totalStyle.FillColor.Should().Be(new CellColor(169, 208, 142));
        totalStyle.FontColor.Should().Be(new CellColor(0, 97, 0));
        totalStyle.Bold.Should().BeTrue();
        loaded.GetStyle(loadedSheet.GetCell(new CellAddress(loadedSheet.Id, 5, 4))!.StyleId)
            .FillColor.Should().Be(new CellColor(234, 220, 248));

        var loadedColumnSheet = loaded.GetSheetAt(1);
        loaded.GetStyle(loadedColumnSheet.GetCell(new CellAddress(loadedColumnSheet.Id, 2, 1))!.StyleId)
            .FillColor.Should().Be(new CellColor(217, 234, 211));
        loaded.GetStyle(loadedColumnSheet.GetCell(new CellAddress(loadedColumnSheet.Id, 2, 2))!.StyleId)
            .FillColor.Should().Be(new CellColor(234, 220, 248));
        loaded.GetStyle(loadedColumnSheet.GetCell(new CellAddress(loadedColumnSheet.Id, 2, 3))!.StyleId)
            .FillColor.Should().Be(new CellColor(234, 220, 248));
        loaded.GetStyle(loadedColumnSheet.GetCell(new CellAddress(loadedColumnSheet.Id, 2, 4))!.StyleId)
            .FillColor.Should().Be(new CellColor(217, 234, 211));

        var saved = new MemoryStream();
        adapter.Save(loaded, saved);
        saved.Position = 0;
        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: false);
        var stylesText = LoadPackageXml(archive.GetEntry("xl/styles.xml")!)
            .ToString(System.Xml.Linq.SaveOptions.DisableFormatting);
        stylesText.Should().Contain("unsupportedSemantics=\"kept\"");
    }

    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_PreservesStableDocumentProperties()
    {
        var workbook = new Workbook("DocumentPropertiesRetentionTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("document properties"));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddStableDocumentProperties(source);
        AddMalformedCorePropertiesRelationship(source);

        source.Position = 0;
        var loaded = adapter.Load(source);
        loaded.GetSheetAt(0).SetCell(new CellAddress(loaded.GetSheetAt(0).Id, 2, 1), new TextValue("edited"));

        var saved = new MemoryStream();
        adapter.Save(loaded, saved);
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: false);
        archive.Entries
            .Select(entry => entry.FullName)
            .Should()
            .NotContain(entryName => entryName.StartsWith("package/services/metadata/core-properties/", StringComparison.OrdinalIgnoreCase));
        var rootRelationships = LoadPackageXml(archive.GetEntry("_rels/.rels")!);
        XNamespace relationshipNs = "http://schemas.openxmlformats.org/package/2006/relationships";
        rootRelationships.Root!
            .Elements(relationshipNs + "Relationship")
            .Where(relationship =>
                relationship.Attribute("Type")?.Value == "http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" &&
                relationship.Attribute("Target")?.Value == "docProps/core.xml")
            .Should()
            .ContainSingle();
        rootRelationships.Root
            .Elements(relationshipNs + "Relationship")
            .Where(relationship => string.Equals(
                relationship.Attribute("Target")?.Value?.TrimStart('/'),
                "docProps/core.xml",
                StringComparison.OrdinalIgnoreCase))
            .Should()
            .ContainSingle();
        rootRelationships.Root
            .Elements(relationshipNs + "Relationship")
            .Where(relationship =>
                relationship.Attribute("Type")?.Value == "http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" &&
                relationship.Attribute("Target")?.Value == "docProps/app.xml")
            .Should()
            .ContainSingle();

        var coreProperties = LoadPackageXml(archive.GetEntry("docProps/core.xml")!);
        XNamespace dcNs = "http://purl.org/dc/elements/1.1/";
        XNamespace cpNs = "http://schemas.openxmlformats.org/package/2006/metadata/core-properties";
        coreProperties.Root!.Element(dcNs + "subject").Should().NotBeNull();
        coreProperties.Root.Element(dcNs + "subject")!.Value.Should().Be("FreeX parity subject");
        coreProperties.Root.Element(cpNs + "keywords").Should().NotBeNull();
        coreProperties.Root.Element(cpNs + "keywords")!.Value.Should().Be("freex,xlsx,parity");
        coreProperties.Root.Element(cpNs + "category").Should().NotBeNull();
        coreProperties.Root.Element(cpNs + "category")!.Value.Should().Be("Native Metadata");
        coreProperties.Root.Element(cpNs + "contentStatus").Should().NotBeNull();
        coreProperties.Root.Element(cpNs + "contentStatus")!.Value.Should().Be("Reviewed");

        var appProperties = LoadPackageXml(archive.GetEntry("docProps/app.xml")!);
        XNamespace appNs = "http://schemas.openxmlformats.org/officeDocument/2006/extended-properties";
        appProperties.Root!.Element(appNs + "Company").Should().NotBeNull();
        appProperties.Root.Element(appNs + "Company")!.Value.Should().Be("FreeX Test Lab");
        appProperties.Root.Element(appNs + "Manager").Should().NotBeNull();
        appProperties.Root.Element(appNs + "Manager")!.Value.Should().Be("XLSX Fidelity");
        appProperties.Root.Element(appNs + "Application").Should().NotBeNull();
        appProperties.Root.Element(appNs + "Application")!.Value.Should().Be("Microsoft Excel");
    }

    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_PreservesCustomDocumentProperties()
    {
        var workbook = new Workbook("CustomDocumentPropertiesRetentionTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("custom document properties"));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddCustomDocumentProperties(source);

        source.Position = 0;
        XlsxFeatureInspector.Inspect(source).Features.Should().Contain(feature => feature.Kind == XlsxUnsupportedFeatureKind.SensitivityLabels);

        source.Position = 0;
        var loaded = adapter.Load(source);
        loaded.GetSheetAt(0).SetCell(new CellAddress(loaded.GetSheetAt(0).Id, 2, 1), new TextValue("edited"));

        var saved = new MemoryStream();
        adapter.Save(loaded, saved);
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: false);
        var rootRelationships = LoadPackageXml(archive.GetEntry("_rels/.rels")!);
        XNamespace relationshipNs = "http://schemas.openxmlformats.org/package/2006/relationships";
        rootRelationships.Root!
            .Elements(relationshipNs + "Relationship")
            .Where(relationship =>
                relationship.Attribute("Type")?.Value == "http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties" &&
                relationship.Attribute("Target")?.Value == "docProps/custom.xml")
            .Should()
            .ContainSingle();
        var customProperties = LoadPackageXml(archive.GetEntry("docProps/custom.xml")!);
        XNamespace customPropertiesNs = "http://schemas.openxmlformats.org/officeDocument/2006/custom-properties";
        XNamespace docPropsVtNs = "http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes";
        customProperties.Root!
            .Elements(customPropertiesNs + "property")
            .Where(property =>
                property.Attribute("name")?.Value == "FreeXCustomProperty" &&
                property.Element(docPropsVtNs + "lpwstr")?.Value == "kept")
            .Should()
            .ContainSingle();
        customProperties.Root
            .Elements(customPropertiesNs + "property")
            .Where(property =>
                property.Attribute("name")?.Value == "MSIP_Label_01234567-89ab-cdef-0123-456789abcdef_Enabled" &&
                property.Element(docPropsVtNs + "lpwstr")?.Value == "true")
            .Should()
            .ContainSingle();

        saved.Position = 0;
        XlsxFeatureInspector.Inspect(saved).Features.Should().Contain(feature => feature.Kind == XlsxUnsupportedFeatureKind.SensitivityLabels);
    }

    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_PreservesUnsupportedWorkbookProperties()
    {
        var workbook = new Workbook("WorkbookPropertiesRetentionTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("properties"));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddUnsupportedWorkbookProperties(source);

        source.Position = 0;
        var loaded = adapter.Load(source);
        loaded.Uses1904DateSystem.Should().BeTrue();
        loaded.Properties.Should().NotBeNull();
        BagAttr(loaded.Properties, "workbookPr", "defaultThemeVersion").Should().Be("166925");
        BagChildren(loaded.Properties, "workbookPr").Should().HaveCount(2);
        BagChildren(loaded.Properties, "workbookPr")[0].Should().Contain("id=\"first\"");
        BagChildren(loaded.Properties, "workbookPr")[1].Should().Contain("id=\"second\"");
        loaded.GetSheetAt(0).SetCell(new CellAddress(loaded.GetSheetAt(0).Id, 2, 1), new TextValue("edited"));

        var saved = new MemoryStream();
        adapter.Save(loaded, saved);
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: false);
        var workbookXml = LoadPackageXml(archive.GetEntry("xl/workbook.xml")!);
        XNamespace workbookNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
        var workbookPr = workbookXml.Root!.Element(workbookNs + "workbookPr");
        workbookPr.Should().NotBeNull();
        workbookPr!.Attribute("date1904").Should().NotBeNull();
        workbookPr.Attribute("date1904")!.Value.Should().Be("1");
        workbookPr.Attribute("defaultThemeVersion")!.Value.Should().Be("166925");
        workbookPr.Elements(XName.Get("workbookPrNativeChild", "urn:freex:test"))
            .Should()
            .BeEmpty();
    }

