    [Fact]
    public void XlsxAdapter_LoadedWorkbookSave_PrunesStaleWorksheetPrinterSettingsRelationships()
    {
        var workbook = new Workbook("PrinterSettingsStaleRelationshipTest");
        var sheet = workbook.AddSheet("Data");
