            pivotFormats.Element(chartNs + "pivotFmt")!.Element(chartNs + "idx")!.Attribute("val")!.Value.Should().Be("0");
            pivotFormats.ToString().Should().Contain("4472C4");
            chartXml.Root.Element(chartNs + "roundedCorners")!.Attribute("val")!.Value.Should().Be("1");
            var protection = chartXml.Root.Element(chartNs + "protection")!;
            protection.Element(chartNs + "chartObject")!.Attribute("val")!.Value.Should().Be("1");
            protection.Element(chartNs + "data")!.Attribute("val")!.Value.Should().Be("1");
            protection.Element(chartNs + "formatting")!.Attribute("val")!.Value.Should().Be("0");
            protection.Element(chartNs + "selection")!.Attribute("val")!.Value.Should().Be("1");
            protection.Element(chartNs + "userInterface")!.Attribute("val")!.Value.Should().Be("1");
            chartXml.Root.Element(chartNs + "chart")!.Element(chartNs + "autoTitleDeleted")!.Attribute("val")!.Value.Should().Be("1");
            chartXml.Root.Element(chartNs + "chart")!.Element(chartNs + "plotVisOnly")!.Attribute("val")!.Value.Should().Be("0");
            chartXml.Root.Element(chartNs + "chart")!.Element(chartNs + "dispBlanksAs")!.Attribute("val")!.Value.Should().Be("zero");
            chartXml.Root.Element(chartNs + "chart")!.Element(chartNs + "showDLblsOverMax")!.Attribute("val")!.Value.Should().Be("1");
            chartXml.Root.Element(chartNs + "pivotSource").Should().NotBeNull();
        }

        saved.Position = 0;
        var loaded = new XlsxFileAdapter().Load(saved);
        var loadedChart = loaded.GetSheetAt(0).Charts.Should().ContainSingle().Which;
        loadedChart.ChartStyleId.Should().Be(42);
        loadedChart.PivotFormatsXml.Should().Contain("4472C4");
        loadedChart.Uses1904DateSystem.Should().BeTrue();
        loadedChart.Language.Should().Be("en-US");
        loadedChart.ColorMapOverride.Should().NotBeNull();
        loadedChart.ColorMapOverride!.UseMasterColorMapping.Should().BeFalse();
        loadedChart.ColorMapOverride.OverrideMappings.Should().BeEquivalentTo(
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["accent1"] = "accent2"
            });
        loadedChart.ExternalData.Should().BeEquivalentTo(chart.ExternalData);
        loadedChart.TitleLayout.Should().BeEquivalentTo(chart.TitleLayout);
        loadedChart.TitleOverlay.Should().BeTrue();
        loadedChart.PlotAreaLayout.Should().BeEquivalentTo(chart.PlotAreaLayout);
        loadedChart.LegendLayout.Should().BeEquivalentTo(chart.LegendLayout);
        loadedChart.ThreeDView.Should().BeEquivalentTo(chart.ThreeDView);
        loadedChart.PrintSettings.Should().BeEquivalentTo(chart.PrintSettings);
        loadedChart.ChartDefaultTextColor.Should().Be(new CellColor(25, 35, 45));
        loadedChart.ChartDefaultFontSize.Should().Be(13);
        loadedChart.RoundedCorners.Should().BeTrue();
        loadedChart.BlankDisplayMode.Should().Be(ChartBlankDisplayMode.Zero);
        loadedChart.ShowDataLabelsOverMaximum.Should().BeTrue();
        loadedChart.AutoTitleDeleted.Should().BeTrue();
        loadedChart.ShowDataInHiddenRowsAndColumns.Should().BeTrue();
        loadedChart.Protection.Should().BeEquivalentTo(new ChartProtectionModel
        {
            ChartObject = true,
            Data = true,
            Formatting = false,
            Selection = true,
            UserInterface = true
        });
    }

    [Fact]
    public void XlsxAdapter_Save_WritesAuthoredPivotTablePackageParts()
    {
        var workbook = new Workbook("AuthoredPivotXlsxTest");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("Category"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 2), new TextValue("Amount"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 1), new TextValue("A"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 2), new NumberValue(10));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 1), new TextValue("B"));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 2), new NumberValue(20));
        workbook.PivotCaches.Add(new PivotCacheModel
        {
            CacheId = 1,
            SourceType = PivotCacheSourceType.WorksheetRange,
            SourceSheetName = "Data",
            SourceReference = "A1:B3"
        });
        workbook.PivotCaches[0].Fields.Add(new PivotCacheFieldModel("Category"));
        workbook.PivotCaches[0].Fields.Add(new PivotCacheFieldModel("Amount"));
        var pivot = new PivotTableModel
        {
            Name = "PivotTable1",
            CacheId = 1,
            CreatedVersion = 6,
            UpdatedVersion = 7,
            MinRefreshableVersion = 5,
            SourceRange = new GridRange(new CellAddress(sheet.Id, 1, 1), new CellAddress(sheet.Id, 3, 2)),
            TargetRange = new GridRange(new CellAddress(sheet.Id, 5, 1), new CellAddress(sheet.Id, 7, 2)),
            DataOnRows = false,
            FirstHeaderRow = 0,
            FirstDataRow = 2,
            FirstDataColumn = 2,
            CompactRowLabelIndent = 4,
            ShowFieldHeaders = false,
            ShowExpandCollapseButtons = false,
            ShowContextualTooltips = false,
            ShowPropertiesInTooltips = false,
            ShowClassicLayout = true,
            MergeAndCenterLabels = true,
            PageOverThenDown = true,
            PageWrap = 2,
            ApplyNumberFormats = false,
            ApplyBorderFormats = false,
            ApplyFontFormats = false,
            ApplyPatternFormats = false,
            AutofitColumnsOnUpdate = false,
            PreserveFormattingOnUpdate = false,
            PrintTitles = true,
            PrintExpandCollapseButtons = true,
            EnableDrill = false,
            AsteriskTotals = true,
            MultipleFieldFilters = false,
            EnableFieldDialog = false,
            EnableFieldProperties = false,
            EnableDataValueEditing = true,
            AltTextTitle = "Sales pivot",
            AltTextDescription = "Pivot summary for sales",
            DataCaption = "Values",
            GrandTotalCaption = "Overall Total",
            MissingCaption = "(missing)",
            ErrorCaption = "(error)"
        };
        pivot.RowFields.Add(new PivotFieldModel(
            0,
            ShowAll: true,
            IncludeNewItemsInFilter: true,
            MultipleItemSelectionAllowed: false,
            DragToRow: true,
            DragToColumn: false,
            DragToPage: true,
            DragToData: false));
        pivot.DataFields.Add(new PivotDataFieldModel(1, "Sum of Amount", "sum", 4));
        sheet.PivotTables.Add(pivot);

        var saved = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, saved);
        saved.Position = 0;

        using (var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: true))
        {
            archive.GetEntry("xl/pivotCache/pivotCacheDefinition1.xml").Should().NotBeNull();
            archive.GetEntry("xl/pivotCache/pivotCacheRecords1.xml").Should().NotBeNull();
            archive.GetEntry("xl/pivotCache/_rels/pivotCacheDefinition1.xml.rels").Should().NotBeNull();
            archive.GetEntry("xl/pivotTables/pivotTable1.xml").Should().NotBeNull();
            var workbookXml = LoadPackageXml(archive.GetEntry("xl/workbook.xml")!);
            workbookXml.ToString().Should().Contain("pivotCaches");
            // The pivot table is linked to its worksheet through a schema-valid worksheet-rels pivotTable
            // relationship (not a worksheet-embedded pivotTableDefinition element, which is not valid OOXML).
            var worksheetRelsXml = LoadPackageXml(archive.GetEntry("xl/worksheets/_rels/sheet1.xml.rels")!);
            worksheetRelsXml.ToString().Should().Contain("relationships/pivotTable");
            var pivotXml = LoadPackageXml(archive.GetEntry("xl/pivotTables/pivotTable1.xml")!);
            XNamespace workbookNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
            XNamespace relNs = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
            var contentTypesXml = LoadPackageXml(archive.GetEntry("[Content_Types].xml")!);
            contentTypesXml.ToString().Should().Contain("/xl/pivotCache/pivotCacheRecords1.xml");
            var cacheXml = LoadPackageXml(archive.GetEntry("xl/pivotCache/pivotCacheDefinition1.xml")!);
            // Fix 5: each cache gets a numbered rel-id so multiple caches get distinct ids.
            cacheXml.Root!.Attribute(relNs + "id")!.Value.Should().Be("rIdPivotCacheRecords1");
            cacheXml.Root!.Attribute("recordCount")!.Value.Should().Be("2");
            var cacheRelsXml = LoadPackageXml(archive.GetEntry("xl/pivotCache/_rels/pivotCacheDefinition1.xml.rels")!);
            cacheRelsXml.ToString().Should().Contain("pivotCacheRecords");
            cacheRelsXml.ToString().Should().Contain("Target=\"pivotCacheRecords1.xml\"");
            var recordsXml = LoadPackageXml(archive.GetEntry("xl/pivotCache/pivotCacheRecords1.xml")!);
            recordsXml.Root!.Attribute("count")!.Value.Should().Be("2");
            recordsXml.ToString().Should().Contain("<s v=\"A\"");
            recordsXml.ToString().Should().Contain("<n v=\"10\"");
            pivotXml.ToString().Should().Contain("rowFields");
            pivotXml.ToString().Should().Contain("dataFields");
            pivotXml.Root!.Attribute("dataOnRows")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("createdVersion")!.Value.Should().Be("6");
            pivotXml.Root!.Attribute("updatedVersion")!.Value.Should().Be("7");
            pivotXml.Root!.Attribute("minRefreshableVersion")!.Value.Should().Be("5");
            pivotXml.Root!.Element(workbookNs + "location")!.Attribute("firstHeaderRow")!.Value.Should().Be("0");
            pivotXml.Root!.Element(workbookNs + "location")!.Attribute("firstDataRow")!.Value.Should().Be("2");
            pivotXml.Root!.Element(workbookNs + "location")!.Attribute("firstDataCol")!.Value.Should().Be("2");
            pivotXml.Root!.Attribute("itemPrintTitles")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("fieldPrintTitles")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("showDrill")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("showHeaders")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("showDataTips")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("showMemberPropertyTips")!.Value.Should().Be("0");
            // ShowClassicLayout maps to the OOXML gridDropZones attribute (Classic PivotTable Layout /
            // "enables dragging of fields in the grid"), NOT showDropZones (an unrelated, unmodeled flag
            // that is left at its schema default and therefore omitted).
            pivotXml.Root!.Attribute("gridDropZones")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("showDropZones").Should().BeNull();
            pivotXml.Root!.Attribute("mergeItem")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("pageOverThenDown")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("pageWrap")!.Value.Should().Be("2");
            pivotXml.Root!.Attribute("applyNumberFormats")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("applyBorderFormats")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("applyFontFormats")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("applyPatternFormats")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("applyWidthHeightFormats")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("preserveFormatting")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("printDrill")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("enableDrill")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("asteriskTotals")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("multipleFieldFilters")!.Value.Should().Be("0");
            // OOXML uses disableFieldList (inverse of EnableFieldDialog=false => "1") and editData.
            pivotXml.Root!.Attribute("disableFieldList")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("enableFieldProperties")!.Value.Should().Be("0");
            pivotXml.Root!.Attribute("editData")!.Value.Should().Be("1");
            pivotXml.Root!.Attribute("indent")!.Value.Should().Be("4");
            pivotXml.Root!.Attribute("altText").Should().BeNull();
            pivotXml.Root!.Attribute("altTextSummary").Should().BeNull();
            XNamespace freeXPivotNs = "urn:freex:pivot:2026";
            var tableProps = pivotXml.Root!
                .Element(workbookNs + "extLst")!
                .Descendants(freeXPivotNs + "tableProps")
                .Should().ContainSingle().Subject;
            tableProps.Attribute("altTextTitle")!.Value.Should().Be("Sales pivot");
            tableProps.Attribute("altTextDescription")!.Value.Should().Be("Pivot summary for sales");
            pivotXml.Root!.Attribute("dataCaption")!.Value.Should().Be("Values");
            pivotXml.Root!.Attribute("grandTotalCaption")!.Value.Should().Be("Overall Total");
            pivotXml.Root!.Attribute("missingCaption")!.Value.Should().Be("(missing)");
            pivotXml.Root!.Attribute("errorCaption")!.Value.Should().Be("(error)");
            var pivotFields = pivotXml.Root!.Element(workbookNs + "pivotFields")!
                .Elements(workbookNs + "pivotField")
                .ToList();
            var firstPivotField = pivotFields.First();
            firstPivotField.Attribute("showAll")!.Value.Should().Be("1");
            firstPivotField.Attribute("includeNewItemsInFilter")!.Value.Should().Be("1");
            firstPivotField.Attribute("multipleItemSelectionAllowed")!.Value.Should().Be("0");
            firstPivotField.Attribute("dragToRow")!.Value.Should().Be("1");
            firstPivotField.Attribute("dragToCol")!.Value.Should().Be("0");
            firstPivotField.Attribute("dragToPage")!.Value.Should().Be("1");
            firstPivotField.Attribute("dragToData")!.Value.Should().Be("0");
            pivotFields[1].Attribute("dataField")!.Value.Should().Be("1");
        }

        saved.Position = 0;
        var loaded = adapter.Load(saved);
        loaded.PivotCaches.Should().ContainSingle().Which.Fields.Select(field => field.Name)
            .Should().Equal("Category", "Amount");
        var loadedPivot = loaded.GetSheetAt(0).PivotTables.Should().ContainSingle().Subject;
        loadedPivot.DataFields.Should().ContainSingle().Which.NumberFormatId.Should().Be(4);
        var loadedRowField = loadedPivot.RowFields.Should().ContainSingle().Subject;
        loadedRowField.ShowAll.Should().BeTrue();
        loadedRowField.IncludeNewItemsInFilter.Should().BeTrue();
        loadedRowField.MultipleItemSelectionAllowed.Should().BeFalse();
        loadedRowField.DragToRow.Should().BeTrue();
        loadedRowField.DragToColumn.Should().BeFalse();
        loadedRowField.DragToPage.Should().BeTrue();
        loadedRowField.DragToData.Should().BeFalse();
        loadedPivot.CreatedVersion.Should().Be(6);
        loadedPivot.UpdatedVersion.Should().Be(7);
        loadedPivot.MinRefreshableVersion.Should().Be(5);
        loadedPivot.DataOnRows.Should().BeFalse();
        loadedPivot.FirstHeaderRow.Should().Be(0);
        loadedPivot.FirstDataRow.Should().Be(2);
        loadedPivot.FirstDataColumn.Should().Be(2);
        loadedPivot.CompactRowLabelIndent.Should().Be(4);
        loadedPivot.ShowExpandCollapseButtons.Should().BeFalse();
        loadedPivot.ShowFieldHeaders.Should().BeFalse();
        loadedPivot.ShowContextualTooltips.Should().BeFalse();
        loadedPivot.ShowPropertiesInTooltips.Should().BeFalse();
        loadedPivot.ShowClassicLayout.Should().BeTrue();
        loadedPivot.MergeAndCenterLabels.Should().BeTrue();
        loadedPivot.PageOverThenDown.Should().BeTrue();
        loadedPivot.PageWrap.Should().Be(2);
        loadedPivot.ApplyNumberFormats.Should().BeFalse();
        loadedPivot.ApplyBorderFormats.Should().BeFalse();
        loadedPivot.ApplyFontFormats.Should().BeFalse();
        loadedPivot.ApplyPatternFormats.Should().BeFalse();
        loadedPivot.AutofitColumnsOnUpdate.Should().BeFalse();
        loadedPivot.PreserveFormattingOnUpdate.Should().BeFalse();
        loadedPivot.PrintTitles.Should().BeTrue();
        loadedPivot.PrintExpandCollapseButtons.Should().BeTrue();
        loadedPivot.EnableDrill.Should().BeFalse();
        loadedPivot.AsteriskTotals.Should().BeTrue();
        loadedPivot.MultipleFieldFilters.Should().BeFalse();
        loadedPivot.EnableFieldDialog.Should().BeFalse();
        loadedPivot.EnableFieldProperties.Should().BeFalse();
        loadedPivot.EnableDataValueEditing.Should().BeTrue();
        loadedPivot.AltTextTitle.Should().Be("Sales pivot");
        loadedPivot.AltTextDescription.Should().Be("Pivot summary for sales");
        loadedPivot.DataCaption.Should().Be("Values");
        loadedPivot.GrandTotalCaption.Should().Be("Overall Total");
        loadedPivot.MissingCaption.Should().Be("(missing)");
        loadedPivot.ErrorCaption.Should().Be("(error)");
    }

    [Fact]
    public void XlsxAdapter_SaveLoad_RoundTripsPivotCustomValueNumberFormatCatalog()
    {
        var workbook = new Workbook("AuthoredPivotCustomNumberFormatXlsxTest");
        workbook.NumberFormatCatalog[165] = "#,##0.0 \"kg\"";
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("Category"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 2), new TextValue("Amount"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 1), new TextValue("A"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 2), new NumberValue(10));
        workbook.PivotCaches.Add(new PivotCacheModel
        {
            CacheId = 1,
            SourceType = PivotCacheSourceType.WorksheetRange,
            SourceSheetName = "Data",
            SourceReference = "A1:B2"
        });
        workbook.PivotCaches[0].Fields.Add(new PivotCacheFieldModel("Category"));
        workbook.PivotCaches[0].Fields.Add(new PivotCacheFieldModel("Amount"));
        var pivot = new PivotTableModel
        {
            Name = "PivotTable1",
            CacheId = 1,
            SourceRange = new GridRange(new CellAddress(sheet.Id, 1, 1), new CellAddress(sheet.Id, 2, 2)),
            TargetRange = new GridRange(new CellAddress(sheet.Id, 5, 1), new CellAddress(sheet.Id, 7, 2))
        };
        pivot.RowFields.Add(new PivotFieldModel(0));
        pivot.DataFields.Add(new PivotDataFieldModel(
            1,
            "Sum of Amount",
            "sum",
            NumberFormatId: 165,
            NumberFormatCode: "#,##0.0 \"kg\""));
        sheet.PivotTables.Add(pivot);

        var saved = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, saved);
        saved.Position = 0;

        using (var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: true))
        {
            var stylesXml = LoadPackageXml(archive.GetEntry("xl/styles.xml")!);
            stylesXml.ToString().Should().Contain("numFmtId=\"165\"");
            stylesXml.ToString().Should().Contain("formatCode=\"#,##0.0 &quot;kg&quot;\"");
            var pivotXml = LoadPackageXml(archive.GetEntry("xl/pivotTables/pivotTable1.xml")!);
            pivotXml.ToString().Should().Contain("numFmtId=\"165\"");
        }

        saved.Position = 0;
        var loaded = adapter.Load(saved);
        loaded.NumberFormatCatalog.Should().Contain(165, "#,##0.0 \"kg\"");
        var loadedField = loaded.GetSheetAt(0).PivotTables.Should().ContainSingle().Subject.DataFields
            .Should().ContainSingle().Subject;
        loadedField.NumberFormatId.Should().Be(165);
        loadedField.NumberFormatCode.Should().Be("#,##0.0 \"kg\"");
    }

    [Fact]
    public void XlsxAdapter_SaveLoad_RemapPivotCustomNumberFormatWhenCellStylesUseSameId()
    {
        var workbook = new Workbook("PivotCustomNumberFormatCollisionXlsxTest");
        workbook.NumberFormatCatalog[164] = "#,##0.0 \"kg\"";
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("Category"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 2), new TextValue("Amount"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 1), new TextValue("A"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 2), new NumberValue(10));
        var conflictingStyle = CellStyle.Default.Clone();
        conflictingStyle.NumberFormat = "0.0000";
        var styledCell = Cell.FromValue(new NumberValue(10));
        styledCell.StyleId = workbook.RegisterStyle(conflictingStyle);
        sheet.SetCell(new CellAddress(sheet.Id, 2, 2), styledCell);
        workbook.PivotCaches.Add(new PivotCacheModel
        {
            CacheId = 1,
            SourceType = PivotCacheSourceType.WorksheetRange,
            SourceSheetName = "Data",
            SourceReference = "A1:B2"
        });
        workbook.PivotCaches[0].Fields.Add(new PivotCacheFieldModel("Category"));
        workbook.PivotCaches[0].Fields.Add(new PivotCacheFieldModel("Amount"));
        var pivot = new PivotTableModel
        {
            Name = "PivotTable1",
            CacheId = 1,
            SourceRange = new GridRange(new CellAddress(sheet.Id, 1, 1), new CellAddress(sheet.Id, 2, 2)),
            TargetRange = new GridRange(new CellAddress(sheet.Id, 5, 1), new CellAddress(sheet.Id, 7, 2))
        };
        pivot.RowFields.Add(new PivotFieldModel(0));
        pivot.DataFields.Add(new PivotDataFieldModel(
            1,
            "Sum of Amount",
            "sum",
            NumberFormatId: 164,
            NumberFormatCode: "#,##0.0 \"kg\""));
        sheet.PivotTables.Add(pivot);

        var saved = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, saved);
        saved.Position = 0;

        using (var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: true))
        {
            var stylesText = LoadPackageXml(archive.GetEntry("xl/styles.xml")!).ToString();
            stylesText.Should().Contain("formatCode=\"0.0000\"");
            stylesText.Should().Contain("formatCode=\"#,##0.0 &quot;kg&quot;\"");
            var pivotText = LoadPackageXml(archive.GetEntry("xl/pivotTables/pivotTable1.xml")!).ToString();
            pivotText.Should().NotContain("numFmtId=\"164\"");
        }

        saved.Position = 0;
        var loaded = adapter.Load(saved);
        var loadedField = loaded.GetSheetAt(0).PivotTables.Should().ContainSingle().Subject.DataFields
            .Should().ContainSingle().Subject;
        loadedField.NumberFormatId.Should().NotBe(164);
        loadedField.NumberFormatCode.Should().Be("#,##0.0 \"kg\"");
        loaded.NumberFormatCatalog[loadedField.NumberFormatId!.Value].Should().Be("#,##0.0 \"kg\"");
    }

