    [Fact]
    public void XlsxAdapter_SaveLoad_RoundTripsPivotCacheRefreshFlags()
    {
        var workbook = new Workbook("PivotCacheFlagsRoundTrip");
        var sheet = workbook.AddSheet("Data");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("Category"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 2), new TextValue("Amount"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 1), new TextValue("A"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 2), new NumberValue(10));
        var cache = new PivotCacheModel
        {
            CacheId = 1,
            SourceType = PivotCacheSourceType.WorksheetRange,
            SourceSheetName = "Data",
            SourceReference = "A1:B2",
            RefreshOnLoad = false,
            SaveData = false,
            EnableRefresh = false,
            PreserveSourceSortFilter = false,
            MissingItemsLimit = 0,
            RecordCount = 1,
            CreatedVersion = 8,
            MinRefreshableVersion = 4,
            RefreshedVersion = 7,
            RefreshedBy = "FreeX Tests",
            RefreshedDateIso = "2026-05-24T12:34:56Z"
        };
        cache.Fields.Add(new PivotCacheFieldModel("Category"));
        cache.Fields.Add(new PivotCacheFieldModel("Amount"));
        workbook.PivotCaches.Add(cache);
        var pivot = new PivotTableModel
        {
            Name = "PivotTable1",
            CacheId = 1,
            SourceRange = new GridRange(new CellAddress(sheet.Id, 1, 1), new CellAddress(sheet.Id, 2, 2)),
            TargetRange = new GridRange(new CellAddress(sheet.Id, 4, 1), new CellAddress(sheet.Id, 7, 3))
        };
        pivot.RowFields.Add(new PivotFieldModel(0));
        pivot.DataFields.Add(new PivotDataFieldModel(1, "Sum of Amount", "sum"));
        sheet.PivotTables.Add(pivot);

        var saved = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, saved);
        saved.Position = 0;

        using (var archive = new ZipArchive(saved, ZipArchiveMode.Read, leaveOpen: true))
        {
            var cacheXml = LoadPackageXml(archive.GetEntry("xl/pivotCache/pivotCacheDefinition1.xml")!).ToString();
            cacheXml.Should().Contain("refreshOnLoad=\"0\"");
            cacheXml.Should().Contain("saveData=\"0\"");
            cacheXml.Should().Contain("enableRefresh=\"0\"");
            cacheXml.Should().Contain("missingItemsLimit=\"0\"");
            cacheXml.Should().Contain("recordCount=\"1\"");
            cacheXml.Should().Contain("createdVersion=\"8\"");
            cacheXml.Should().Contain("minRefreshableVersion=\"4\"");
            cacheXml.Should().Contain("refreshedVersion=\"7\"");
            cacheXml.Should().Contain("refreshedBy=\"FreeX Tests\"");
            // preserveSourceSortFilter and the ISO refreshed date are not OOXML cacheDefinition attributes;
            // FreeX persists them in a schema-valid extLst extension (keeps the cache part Excel-openable).
            cacheXml.Should().Contain("{FREEX-PIVOT-CACHE-EXT}");
            cacheXml.Should().Contain("preserveSourceSortFilter=\"0\"");
            cacheXml.Should().Contain("refreshedDateIso=\"2026-05-24T12:34:56Z\"");
        }

        saved.Position = 0;
        var loaded = adapter.Load(saved);
        var loadedCache = loaded.PivotCaches.Should().ContainSingle().Subject;
        loadedCache.RefreshOnLoad.Should().BeFalse();
        loadedCache.SaveData.Should().BeFalse();
        loadedCache.EnableRefresh.Should().BeFalse();
        loadedCache.PreserveSourceSortFilter.Should().BeFalse();
        loadedCache.MissingItemsLimit.Should().Be(0);
        loadedCache.RecordCount.Should().Be(1);
        loadedCache.CreatedVersion.Should().Be(8);
        loadedCache.MinRefreshableVersion.Should().Be(4);
        loadedCache.RefreshedVersion.Should().Be(7);
        loadedCache.RefreshedBy.Should().Be("FreeX Tests");
        loadedCache.RefreshedDateIso.Should().Be("2026-05-24T12:34:56Z");
    }

