    [Fact]
    public void XlsxAdapter_LoadSave_RoundTripsStructuredTableRootNativeMetadata()
    {
        var workbook = CreateStructuredTableWorkbook("StructuredTableRootMetadataTest");

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddMinimalStructuredTablePackage(source, includeRootMetadata: true);

        source.Position = 0;
        var loaded = adapter.Load(source);

        var table = loaded.GetSheetAt(0).StructuredTables.Should().ContainSingle().Subject;
        table.Published.Should().BeTrue();
        table.Comment.Should().Be("FreeX root comment");
        table.HeaderRowCount.Should().Be(1);
        table.TotalsRowCount.Should().Be(0);
        table.InsertRow.Should().BeFalse();
        table.InsertRowShift.Should().BeFalse();
        table.NativeAttributes.Should().NotContainKey("published");
        table.NativeAttributes.Should().NotContainKey("comment");
        table.NativeAttributes.Should().NotContainKey("headerRowCount");
        table.NativeAttributes.Should().NotContainKey("totalsRowCount");
        table.NativeAttributes.Should().NotContainKey("insertRow");
        table.NativeAttributes.Should().NotContainKey("insertRowShift");
        table.NativeAttributes.Should().ContainKey("headerRowDxfId").WhoseValue.Should().Be("2");
        table.NativeChildXmls.Should().ContainSingle()
            .Which.Should().Contain("{FREEX-TABLE-ROOT-EXT}");

        var saved = new MemoryStream();
        adapter.Save(loaded, saved);
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read);
        var tableXml = LoadPackageXml(archive.GetEntry("xl/tables/table1.xml")!).ToString(System.Xml.Linq.SaveOptions.DisableFormatting);
        tableXml.Should().Contain("published=\"1\"");
        tableXml.Should().Contain("comment=\"FreeX root comment\"");
        tableXml.Should().Contain("headerRowCount=\"1\"");
        tableXml.Should().Contain("totalsRowCount=\"0\"");
        tableXml.Should().Contain("insertRow=\"0\"");
        tableXml.Should().Contain("insertRowShift=\"0\"");
        tableXml.Should().Contain("headerRowDxfId=\"2\"");
        tableXml.Should().Contain("extLst");
        tableXml.Should().Contain("{FREEX-TABLE-ROOT-EXT}");
    }

    [Fact]
    public void XlsxAdapter_FreshSave_SkipsInvalidStructuredTableNativeAttributeNames()
    {
        var workbook = CreateStructuredTableWorkbook("StructuredTableInvalidNativeAttributesTest");
        var sheet = workbook.GetSheetAt(0);
        var table = new StructuredTableModel
        {
            Id = 1,
            Name = "Table1",
            DisplayName = "Table1",
            Range = new GridRange(new CellAddress(sheet.Id, 1, 1), new CellAddress(sheet.Id, 3, 2)),
            HasAutoFilter = true,
            TotalsRowShown = false,
            StyleName = "TableStyleMedium2",
            ShowRowStripes = true,
            NativeAttributes = new Dictionary<string, string>
            {
                ["headerRowDxfId"] = "2",
                ["invalid table attr"] = "skip"
            },
            NativeAutoFilterAttributes = new Dictionary<string, string>
            {
                ["customAutoFilterFlag"] = "keep",
                ["invalid autoFilter attr"] = "skip"
            },
            NativeStyleInfoAttributes = new Dictionary<string, string>
            {
                ["pivot"] = "0",
                ["invalid styleInfo attr"] = "skip"
            }
        };
        table.Columns.Add(new StructuredTableColumnModel(
            1,
            "Category",
            NativeAttributes: new Dictionary<string, string>
            {
                ["uniqueName"] = "CategoryNative",
                ["invalid column attr"] = "skip"
            }));
        table.Columns.Add(new StructuredTableColumnModel(2, "Amount"));
        table.FilterColumns.Add(new StructuredTableFilterColumnModel(
            0,
            ["A"],
            IncludeBlank: false,
            NativeFilterXmls: [],
            NativeAttributes: new Dictionary<string, string>
            {
                ["hiddenButton"] = "1",
                ["invalid filterColumn attr"] = "skip"
            }));
        sheet.StructuredTables.Add(table);

        var saved = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        var save = () => adapter.Save(workbook, saved);

        save.Should().NotThrow();
        saved.Position = 0;

        using var archive = new ZipArchive(saved, ZipArchiveMode.Read);
        var tableXml = LoadPackageXml(archive.GetEntry("xl/tables/table1.xml")!).ToString(System.Xml.Linq.SaveOptions.DisableFormatting);
        tableXml.Should().Contain("headerRowDxfId=\"2\"");
        tableXml.Should().NotContain("customAutoFilterFlag=\"keep\"");
        tableXml.Should().Contain("pivot=\"0\"");
        tableXml.Should().Contain("uniqueName=\"CategoryNative\"");
        tableXml.Should().Contain("hiddenButton=\"1\"");
        tableXml.Should().NotContain("invalid ");
    }

    [Fact]
    public void XlsxAdapter_Load_MaterializesStructuredTableAutoFilterValuesIntoHiddenRows()
    {
        var workbook = CreateStructuredTableWorkbook("StructuredTableFilterVisibilityTest");
        var sheet = workbook.GetSheetAt(0);
        sheet.SetCell(new CellAddress(sheet.Id, 3, 1), new TextValue("C"));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddMinimalStructuredTablePackage(source, includeFilterValues: true);

        source.Position = 0;
        var loaded = adapter.Load(source);
        var loadedSheet = loaded.GetSheetAt(0);

        loadedSheet.StructuredTables.Should().ContainSingle();
        loadedSheet.FilterHiddenRows.Should().BeEquivalentTo([3u]);
        loadedSheet.HiddenRows.Should().BeEmpty();
    }

    [Fact]
    public void XlsxAdapter_Load_StructuredTableAutoFilterDoesNotHideTotalsRow()
    {
        var workbook = CreateStructuredTableWorkbook("StructuredTableTotalsFilterVisibilityTest");
        var sheet = workbook.GetSheetAt(0);
        sheet.SetCell(new CellAddress(sheet.Id, 3, 1), new TextValue("C"));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 1), new TextValue("Grand Total"));
        sheet.SetCell(new CellAddress(sheet.Id, 4, 2), new NumberValue(30));

        var source = new MemoryStream();
        var adapter = new XlsxFileAdapter();
        adapter.Save(workbook, source);
        source.Position = 0;
        AddMinimalStructuredTablePackage(source, includeTotalsRow: true, includeFilterValues: true);

