    private static void AddMinimalVbaProjectPackage(MemoryStream packageStream)
    {
        using (var archive = new ZipArchive(packageStream, ZipArchiveMode.Update, leaveOpen: true))
        {
            XNamespace packageRelNs = "http://schemas.openxmlformats.org/package/2006/relationships";
            XNamespace contentTypeNs = "http://schemas.openxmlformats.org/package/2006/content-types";

            archive.GetEntry("xl/vbaProject.bin")?.Delete();
            var vbaEntry = archive.CreateEntry("xl/vbaProject.bin");
            using (var stream = vbaEntry.Open())
            {
                stream.Write([0xD0, 0xCF, 0x11, 0xE0]);
            }

            var contentTypesXml = LoadPackageXml(archive.GetEntry("[Content_Types].xml")!);
            var workbookOverride = contentTypesXml.Root!
                .Elements(contentTypeNs + "Override")
                .FirstOrDefault(element => (string?)element.Attribute("PartName") == "/xl/workbook.xml");
            if (workbookOverride is null)
            {
                AddContentTypeOverride(
                    contentTypesXml,
                    contentTypeNs,
                    "/xl/workbook.xml",
                    "application/vnd.ms-excel.sheet.macroEnabled.main+xml");
            }
            else
            {
                workbookOverride.SetAttributeValue("ContentType", "application/vnd.ms-excel.sheet.macroEnabled.main+xml");
            }

            AddContentTypeOverride(contentTypesXml, contentTypeNs, "/xl/vbaProject.bin", "application/vnd.ms-office.vbaProject");
            ReplacePackageXml(archive, "[Content_Types].xml", contentTypesXml);

            var workbookRelsXml = LoadPackageXml(archive.GetEntry("xl/_rels/workbook.xml.rels")!);
            workbookRelsXml.Root!.Add(new XElement(
                packageRelNs + "Relationship",
                new XAttribute("Id", "rIdVbaProject"),
                new XAttribute("Type", "http://schemas.microsoft.com/office/2006/relationships/vbaProject"),
                new XAttribute("Target", "vbaProject.bin")));
            ReplacePackageXml(archive, "xl/_rels/workbook.xml.rels", workbookRelsXml);
        }

        packageStream.Position = 0;
    }

    private static XDocument LoadPackageXml(ZipArchiveEntry entry) =>
        XlsxPackageTestFixtures.LoadPackageXml(entry);

    private static XElement? ReadWorksheetSingleCellTableRootElement(ZipArchive archive)
    {
        XNamespace packageRelNs = "http://schemas.openxmlformats.org/package/2006/relationships";
        const string worksheetPath = "xl/worksheets/sheet1.xml";
        const string relationshipType = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/tableSingleCells";

        var relsEntry = archive.GetEntry("xl/worksheets/_rels/sheet1.xml.rels");
        if (relsEntry is null)
            return null;

        var relsXml = LoadPackageXml(relsEntry);
        var relationship = relsXml.Root?
            .Elements(packageRelNs + "Relationship")
            .FirstOrDefault(element => element.Attribute("Type")?.Value == relationshipType);
        var target = relationship?.Attribute("Target")?.Value;
        if (string.IsNullOrWhiteSpace(target))
            return null;

        var partPath = XlsxPackagePath.ResolveRelationshipTarget(worksheetPath, target);
        var entry = archive.GetEntry(partPath);
        return entry is null ? null : new XElement(LoadPackageXml(entry).Root!);
    }

    private static byte[] ReadPackageEntry(byte[] packageBytes, string path)
    {
        using var stream = new MemoryStream(packageBytes, writable: false);
        using var archive = new ZipArchive(stream, ZipArchiveMode.Read);
        var entry = archive.GetEntry(path);
        entry.Should().NotBeNull();
        using var entryStream = entry!.Open();
        using var bytes = new MemoryStream();
        entryStream.CopyTo(bytes);
        return bytes.ToArray();
    }

    private static string? ReadSheetProtectionAttribute(Stream packageStream, string attributeName)
    {
        var originalPosition = packageStream.CanSeek ? packageStream.Position : 0;
        if (packageStream.CanSeek)
            packageStream.Position = 0;

        try
        {
            using var archive = new ZipArchive(packageStream, ZipArchiveMode.Read, leaveOpen: true);
            var worksheetXml = LoadPackageXml(archive.GetEntry("xl/worksheets/sheet1.xml")!);
            XNamespace worksheetNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
            return worksheetXml.Root?
                .Element(worksheetNs + "sheetProtection")?
                .Attribute(attributeName)?
                .Value;
        }
        finally
        {
            if (packageStream.CanSeek)
                packageStream.Position = originalPosition;
        }
    }

    private static void ReplacePackageXml(ZipArchive archive, string entryName, XDocument document)
    {
        archive.GetEntry(entryName)?.Delete();
        var entry = archive.CreateEntry(entryName);
        using var stream = entry.Open();
        document.Save(stream);
    }

    private static void AddContentTypeOverride(XDocument contentTypesXml, XNamespace contentTypeNs, string partName, string contentType)
    {
        contentTypesXml.Root!
            .Elements(contentTypeNs + "Override")
            .Where(element => string.Equals(element.Attribute("PartName")?.Value, partName, StringComparison.OrdinalIgnoreCase))
            .Remove();
        contentTypesXml.Root!.Add(new XElement(
            contentTypeNs + "Override",
            new XAttribute("PartName", partName),
            new XAttribute("ContentType", contentType)));
    }

    private static void AddIgnorablePrefix(XElement root, XNamespace markupCompatNs, string prefix)
    {
        root.SetAttributeValue(XNamespace.Xmlns + "mc", markupCompatNs.NamespaceName);
        var current = root.Attribute(markupCompatNs + "Ignorable")?.Value ?? "";
        var prefixes = current.Split(' ', StringSplitOptions.RemoveEmptyEntries).ToList();
        if (!prefixes.Any(value => string.Equals(value, prefix, StringComparison.OrdinalIgnoreCase)))
            prefixes.Add(prefix);
        root.SetAttributeValue(markupCompatNs + "Ignorable", string.Join(" ", prefixes));
    }

    private static void EnsureExtensionRef(
        XElement root,
        XNamespace mainNs,
        XNamespace extensionNs,
        string prefix,
        string extensionUri,
        string containerName,
        string childName,
        string relationshipId,
        XNamespace relationshipNs)
    {
        var extensionList = root.Element(mainNs + "extLst");
        if (extensionList is null)
        {
            extensionList = new XElement(mainNs + "extLst");
            root.Add(extensionList);
        }

        var extension = extensionList.Elements(mainNs + "ext")
            .FirstOrDefault(element => string.Equals(element.Attribute("uri")?.Value, extensionUri, StringComparison.OrdinalIgnoreCase));
        if (extension is null)
        {
            extension = new XElement(
                mainNs + "ext",
                new XAttribute("uri", extensionUri),
                new XAttribute(XNamespace.Xmlns + prefix, extensionNs.NamespaceName));
            extensionList.Add(extension);
        }
        else
        {
            extension.SetAttributeValue(XNamespace.Xmlns + prefix, extensionNs.NamespaceName);
        }

        var container = extension.Element(extensionNs + containerName);
        if (container is null)
        {
            container = new XElement(extensionNs + containerName);
            extension.Add(container);
        }

        container.Elements(extensionNs + childName)
            .Where(element => string.Equals(element.Attribute(relationshipNs + "id")?.Value, relationshipId, StringComparison.OrdinalIgnoreCase))
            .Remove();
        container.Add(new XElement(extensionNs + childName, new XAttribute(relationshipNs + "id", relationshipId)));
    }

