    [Fact]
    public void CsvAdapter_RoundTrip()
    {
        var workbook = new Workbook("CsvTest");
        var sheet = workbook.AddSheet("Sheet1");

        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new NumberValue(1));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 2), new NumberValue(2));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 3), new TextValue("hello"));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 1), new NumberValue(4));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 2), new NumberValue(5));
        sheet.SetCell(new CellAddress(sheet.Id, 2, 3), new TextValue("world"));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 1), new NumberValue(7));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 2), new NumberValue(8));
        sheet.SetCell(new CellAddress(sheet.Id, 3, 3), new NumberValue(9));

        var ms = new MemoryStream();
        var adapter = new CsvFileAdapter();
        adapter.Save(workbook, ms);
        ms.Position = 0;
        var loaded = adapter.Load(ms);

        var ls = loaded.GetSheetAt(0);
        ((NumberValue)ls.GetValue(1, 1)).Value.Should().Be(1);
        ((NumberValue)ls.GetValue(1, 2)).Value.Should().Be(2);
        ((TextValue)ls.GetValue(1, 3)).Value.Should().Be("hello");
        ((NumberValue)ls.GetValue(3, 3)).Value.Should().Be(9);
    }

    [Fact]
    public void CsvAdapter_Load_AutoDetectsNumbers()
    {
        const string csv = "1,2,hello\r\n";
        var ms = new MemoryStream(Encoding.UTF8.GetBytes(csv));
        var adapter = new CsvFileAdapter();
        var loaded = adapter.Load(ms);

        var sheet = loaded.GetSheetAt(0);
        sheet.GetValue(1, 1).Should().BeOfType<NumberValue>().Which.Value.Should().Be(1);
        sheet.GetValue(1, 2).Should().BeOfType<NumberValue>().Which.Value.Should().Be(2);
        sheet.GetValue(1, 3).Should().BeOfType<TextValue>().Which.Value.Should().Be("hello");
    }

    [Fact]
    public void CsvLoad_MultilineQuotedField_IsReadAsOneCell()
    {
        var csv = "\"line1\nline2\",second\r\nrow2a,row2b\r\n";
        using var stream = new MemoryStream(Encoding.UTF8.GetBytes(csv));
        var adapter  = new CsvFileAdapter();
        var workbook = adapter.Load(stream);
        var sheet    = workbook.Sheets[0];

        sheet.GetValue(new CellAddress(sheet.Id, 1, 1))
            .Should().Be(new TextValue("line1\nline2"),
                "RFC 4180 allows newlines inside quoted fields");
        sheet.GetValue(new CellAddress(sheet.Id, 1, 2))
            .Should().Be(new TextValue("second"));
        sheet.GetValue(new CellAddress(sheet.Id, 2, 1))
            .Should().Be(new TextValue("row2a"));
    }

    [Fact]
    public void CsvRoundTrip_MultilineField_PreservesContent()
    {
        var wb    = new Workbook("T");
        var sheet = wb.AddSheet("S");
        sheet.SetCell(new CellAddress(sheet.Id, 1, 1), new TextValue("a\nb"));
        sheet.SetCell(new CellAddress(sheet.Id, 1, 2), new TextValue("c"));

        var adapter = new CsvFileAdapter();
        using var ms = new MemoryStream();
        adapter.Save(wb, ms);
        ms.Position = 0;
        var wb2    = adapter.Load(ms);
        var sheet2 = wb2.Sheets[0];
        sheet2.GetValue(new CellAddress(sheet2.Id, 1, 1)).Should().Be(new TextValue("a\nb"));
        sheet2.GetValue(new CellAddress(sheet2.Id, 1, 2)).Should().Be(new TextValue("c"));
    }

    // ── NativeXmlPreserveBag test helpers ────────────────────────────────────

    private static NativeXmlPreserveBag MakeBag(
        string key,
        Dictionary<string, string>? attrs = null,
        IReadOnlyList<string>? children = null)
    {
        var wrapper = new XElement("e");
        foreach (var (name, value) in attrs ?? [])
        {
            try { wrapper.SetAttributeValue(XName.Get(name), value); } catch { }
        }
        foreach (var childXml in children ?? [])
        {
            try { wrapper.Add(XElement.Parse(childXml, System.Xml.Linq.LoadOptions.PreserveWhitespace)); } catch { }
        }
        if (!wrapper.Attributes().Any() && !wrapper.HasElements)
            return new NativeXmlPreserveBag();
        var bag = new NativeXmlPreserveBag();
        bag.Set(key, wrapper.ToString(System.Xml.Linq.SaveOptions.DisableFormatting));
        return bag;
    }

    /// <summary>Gets the value of a named attribute from a NativeXmlPreserveBag entry, or null if absent.</summary>
    private static string? BagAttr(NativeXmlPreserveBag? bag, string key, string attrName)
    {
        if (bag is null) return null;
        var xml = bag.Get(key);
        if (xml is null) return null;
        try { return XElement.Parse(xml).Attribute(attrName)?.Value; } catch { return null; }
    }

    /// <summary>Returns child XML strings from a NativeXmlPreserveBag entry.</summary>
    private static IReadOnlyList<string> BagChildren(NativeXmlPreserveBag? bag, string key)
    {
        if (bag is null) return [];
        var xml = bag.Get(key);
        if (xml is null) return [];
        try
        {
            return XElement.Parse(xml).Elements()
                .Select(e => e.ToString(System.Xml.Linq.SaveOptions.DisableFormatting))
                .ToList();
        }
        catch { return []; }
    }

    private static IReadOnlyList<ConditionalFormat> InvokeReadAdvancedConditionalFormats(
        XDocument worksheetXml,
        XNamespace worksheetNs)
    {
        // Two overloads exist (a 5-arg convenience wrapper and the 6-arg one with the
        // classic-rule-priority out param), so disambiguate by parameter count instead of
        // using the single-match GetMethod overload.
        var method = typeof(XlsxFileAdapter)
            .GetMethods(BindingFlags.NonPublic | BindingFlags.Static)
            .FirstOrDefault(m => m.Name == "ReadAdvancedConditionalFormats" && m.GetParameters().Length == 5);
        method.Should().NotBeNull();
        return (IReadOnlyList<ConditionalFormat>)method!.Invoke(
            null,
            [worksheetXml, worksheetNs, Array.Empty<CellStyle>(), WorkbookTheme.Office, new WorkbookIndexedColorPalette()])!;
    }

    /// <summary>Adds an attribute to the NativeXmlPreserveBag entry for the given key.
    /// If the attribute name is not a valid XML name (e.g. contains spaces), the call is silently ignored —
    /// the bag uses XML serialization internally and cannot store invalid attribute names, which means
    /// writers will never encounter them and don't need to filter them.</summary>
    private static void AddBagAttr(NativeXmlPreserveBag bag, string key, string attrName, string attrValue)
    {
        var xml = bag.Get(key);
        XElement wrapper;
        if (xml is null)
        {
            wrapper = new XElement("e");
        }
        else
        {
            try { wrapper = XElement.Parse(xml); } catch { return; }
        }

        try
        {
            wrapper.SetAttributeValue(attrName, attrValue);
            bag.Set(key, wrapper.ToString(System.Xml.Linq.SaveOptions.DisableFormatting));
        }
        catch (System.Xml.XmlException) { /* invalid attribute name — silently ignore */ }
        catch (ArgumentException) { /* invalid attribute name — silently ignore */ }
    }
}
